entries[239207] = { ["name"] = "Berührung von Sargeras", ["text"] = "Wirken in 2.5 sek. 10 sek. Abklingzeit\nDer gefallene Avatar erschafft 4 schattenhafte Risse. Jeder Riss bricht nach 8 Sek. aus und verursacht 131574 Schattenschaden, der gleichmäßig auf alle Spielercharaktere im Riss aufgeteilt wird. Jeder nicht absorbierte Riss fügt allen Spielercharakteren 94829 Schattenschaden zu." }
