entries[239211] = { ["name"] = "Zenpilgerfahrt", ["text"] = "Wirken in 10 sek. 1 min Abklingzeit\nEuer Geist reist zum Gipfel der Ruhe in Pandaria und lässt Euren Körper zurück.\n\nBenutzt 'Zenpilgerfahrt' erneut, um in die Nähe Eures Ausgangsortes zurückzukehren." }
entries[239212] = { ["name"] = "Lauernde Dunkelheit", ["text"] = "Sofort\nDer Aufprall einer schattenhaften Klinge erschafft eine klebrige Pfütze, die innerhalb ihres Effektbereichs alle 2 Sek. 13877 Schattenschaden verursacht und die Bewegungsgeschwindigkeit um 50% verringert." }
