entries[239214] = { ["name"] = "Riss öffnen", ["text"] = "Unbegrenzte Reichweite\nSofort\nÖffnet einen Realitätsriss, der alle Spielercharaktere zu sich zieht und alle Spielercharaktere, die sich zu nah am Riss befinden, mit 'Gravitationsdruck' belegt.\n\nAuch die Geschosse von 'Dunkelheit der tausend Seelen' werden in den Riss gesogen, wenn sich der anvisierte Spielercharakter nah genug am Riss befindet, um von 'Gravitationsdruck' betroffen zu sein.\n\nSchließlich zieht der Riss auch die von den flammenden Kugeln erschaffenen Flammenfelder zu sich heran. Wenn sie den Rand der Plattform in der Nähe des Risses erreichen, saugt der Riss die Flammen auf und verringert so die Größe des Flammenfelds mit der Zeit." }
entries[239215] = { ["name"] = "Blendender Blick" }
entries[239216] = { ["name"] = "Dunkelheit der tausend Seelen", ["text"] = "Unbegrenzte Reichweite\nSofort\nFeuert tödliche Schattengeschosse auf alle Schlachtzugsmitglieder ab, die allen getroffenen Spielercharakteren sofort 77127 Schattenschaden sowie für den Rest des Kampfes alle 2 Sek. 8218 Schattenschaden zufügen.\n\nWenn ein von 'Dunkelheit der tausend Seelen' anvisierter Spielercharakter sich nah genug an einem Realitätsriss befindet, um von 'Gravitationsdruck' betroffen zu sein, werden die Geschosse des Zaubers schadlos in den Riss gesogen." }
