entries[239412] = { ["name"] = "Celumbra, Dichotomie der Nacht", ["text"] = "Wirken in 2 sek.\nReagenzien:\nSchattenstoffballen , Sternengewebeballen , Nethersplitteressenz , Blut von Sargeras (65), Machtgetränktes Seidengewebe (125), Scharfer Waldgeistdorn , Runenfaden aus Katgut\nStellt Celumbra, Dichotomie der Nacht, her.\nBerufsausbilder:\nSchneiderei der Verheerten Inseln (100)\nKosten:\n250\n\nCelumbra, Dichotomie der Nacht\nWird beim Anlegen gebunden\nEinzigartig anlegbar: Legion - legendär (1)Schulter Stoff\n3 Rüstung\n+4 Intelligenz\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Tempowertung um + 4.\n\nPrismatischer Sockel\nPrismatischer Sockel\nPrismatischer Sockel\n\nHaltbarkeit 120 / 120\nKlassen: Priester , Magier , Hexenmeister\nAnlegen: Wenn sich ein Gegner innerhalb von 12 Metern um Euch befindet, werdet Ihr in Schatten gehüllt, die Euren erlittenen Schaden um 5% verringern und Eure Bewegungsgeschwindigkeit um 10% erhöhen. Wenn sich keine Gegner innerhalb von 12 Metern um Euch befinden, heilt Euch Celumbras Sternenlicht alle 1 Sek. um 1% Eurer maximalen Gesundheit.\n40\n\"Schatten und Sterne, Dunkelheit und Licht, Verzweiflung und Hoffnung.\"" }
entries[239413] = { ["name"] = "Ewiges Refugium der Schildwache", ["text"] = "Wirken in 2 sek.\nReagenzien:\nIrrwischberührter Urbalg , Nethersplitteressenz , Blut von Sargeras (65), Steinbalgleder (250)\nStellt das ewige Refugium der Schildwache her.\nBerufsausbilder:\nLederverarbeitung der Verheerten Inseln (100)\nKosten:\n250\n\nEwiges Refugium der Schildwache\nWird beim Anlegen gebunden\nEinzigartig anlegbar: Legion - legendär (1)Füße Leder\n5 Rüstung\n+4 [Beweglichkeit oder Intelligenz]+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Meisterschaftswertung um + 4.\n\nPrismatischer Sockel\nPrismatischer Sockel\nPrismatischer Sockel\n\nHaltbarkeit 95 / 95\nKlassen: Schurke , Mönch , Druide , Dämonenjäger\nAnlegen: Jedes Mal, wenn Ihr einen Gegner tötet, wird Eure Bewegungsgeschwindigkeit 1 Min. lang um 5% erhöht. Bis zu 5-mal stapelbar. Bei 5 Stapeln verwandelt Ihr Euch außerhalb des Kampfes in einen Irrwisch, was Eure Bewegungsgeschwindigkeit zusätzlich erhöht und Euch die Fähigkeit zu fliegen gewährt.\n40\n\"Ihr Geist erfüllt das Leder dieser Stiefel und wird so an diese Welt gebunden.\"" }
entries[239414] = { ["name"] = "Träger der Weisheit", ["text"] = "Wirken in 2 sek.\nReagenzien:\nErstklassige Wächterschuppen , Nethersplitteressenz , Blut von Sargeras (65), Sturmschuppe (250)\nStellt die Träger der Weisheit her.\nBerufsausbilder:\nLederverarbeitung der Verheerten Inseln (100)\nKosten:\n250\n\nTräger der Weisheit\nWird beim Anlegen gebunden\nEinzigartig anlegbar: Legion - legendär (1)Hände Kette\n7 Rüstung\n+4 [Beweglichkeit oder Intelligenz]+6 Ausdauer\nErhöht Eure Tempowertung um + 3.\nErhöht Eure Meisterschaftswertung um + 4.\n\nPrismatischer Sockel\nPrismatischer Sockel\nPrismatischer Sockel\n\nHaltbarkeit 70 / 70\nKlassen: Jäger , Schamane , Rufer\nAnlegen: Jedes Mal, wenn Ihr einen Gegner tötet, wird Eure Bewegungsgeschwindigkeit 1 Min. lang um 5% erhöht. Bis zu 5-mal stapelbar. Bei 5 Stapeln verwandelt Ihr Euch außerhalb des Kampfes in eine Geistereule, was Eure Bewegungsgeschwindigkeit zusätzlich erhöht und Euch die Fähigkeit zu fliegen gewährt.\n40\n\"Selbst nach dem Tod wachen die Geister der Eulen noch über ihre Meister, solange ein sicher geführter Handschuh sie trägt.\"" }
entries[239415] = { ["name"] = "Rethus unerschöpflicher Mut", ["text"] = "Wirken in 2 sek.\nTools: Schmiedehammer\nReagenzien:\nHammer der vergessenen Helden , Nethersplitteressenz , Blut von Sargeras (65), Dämonenstahlbarren (125)\nStellt Rethus unerschöpflichen Mut her.\nBerufsausbilder:\nSchmiedekunst der Verheerten Inseln (100)\nKosten:\n250\n\nRethus unerschöpflicher Mut\nWird beim Anlegen gebunden\nEinzigartig anlegbar: Legion - legendär (1)Taille Platte\n10 Rüstung\n+4 [Stärke oder Intelligenz]+6 Ausdauer\nErhöht Eure Tempowertung um + 4.\nErhöht Eure Meisterschaftswertung um + 3.\n\nPrismatischer Sockel\nPrismatischer Sockel\nPrismatischer Sockel\n\nHaltbarkeit 70 / 70\nKlassen: Krieger , Paladin , Todesritter\nAnlegen: Wenn sich ein Gegner innerhalb von 8 Metern von Euch befindet, werdet Ihr alle 3 Sek. um 2% Eurer maximalen Gesundheit geheilt. Wenn sich keine Gegner innerhalb von 8 Metern von Euch befinden, wird Eure Bewegungsgeschwindigkeit um 15% erhöht.\n40\n\"Sein Mut wirkte ansteckend.\"" }
