entries[239645] = { ["name"] = "Teufelsschätze", ["text"] = "Sofort\nWenn Ihr den Bau des Magierturms abschließt, erhaltet Ihr Zugriff auf:\n\nArtefaktherausforderungen\nDer Rat der Sechs gewährt Zugriff auf eine Reihe einzigartiger Herausforderungen, bei denen würdige Helden ihre Kraft und ihr Geschick auf die Probe stellen können.\n\nVerhüllte Wyrmzungenschatztruhen\nDie Macht des Magierturms pulsiert über die Verheerte Küste hinweg und offenbart die lukrativen verhüllten Wyrmzungenschatztruhen.\n\nPortalnetzwerk\nDie Kirin Tor gewähren Zugang zu Portalen, mit denen Ihr Euch schnell über die Verheerten Inseln bewegen könnt." }
entries[239646] = { ["name"] = "Umarmung des Lichts", ["text"] = "Sofort\nSchützt vor Schaden." }
entries[239647] = { ["name"] = "Epischer Jäger", ["text"] = "Sofort\nWenn Ihr den Bau des Netherdisruptors abschließt, erhaltet Ihr Zugriff auf:\n\nWeltbosse\nDie Energie des Netherdisruptors zieht die mächtigsten Gegner zur Verheerten Küste.\n\nInstabile Netherportale\nDie Aktivierung des Netherdisruptors lässt überall an der Verheerten Küste instabile Netherportale entstehen. Aktiviert sie, um gefährliche Gegner zu beschwören.\n\nBelobigungen des Rüstungsmachers\nDie geschicktesten Handwerker werden für ihre Anstrengungen Belobigungen erhalten, mit denen sie legendäre Gegenstände herstellen können." }
entries[239648] = { ["name"] = "Streitkräfte des Ordens", ["text"] = "Sofort\nNachdem der Bau der Kommandozentrale abgeschlossen ist, erhaltet Ihr Zugriff auf:\n\nKathedralenweltquests\nJetzt, da die Kommandozentrale erbaut ist, könnt Ihr Euch darauf konzentrieren, die Kathedrale der Ewigen Nacht anzugreifen.\n\nVerstärkungstruppen der Legionsrichter\nKommandanten der Legionsrichter können überall auf den Verheerten Inseln zusätzliche Verstärkung anfordern.\n\nEliteeinsatz\nSendet würdige Champions auf eine herausfordernde, aber lukrative Mission tief ins Inland der Verheerten Küste." }
